Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('2411185f45ae8b7860dc121fbd05300bfca099d8a5dc02f056d468bd22c31fdd',), event=Revised(decision='filesasthemselves', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title='A PDF or an image reaches the model as itself, unless its text names an ID number', body="Since 2026-09-29 a PDF or an image reaches the model AS ITSELF (`suzatary_held::file_read`, the `email-attachments-jakuay` report): `FileRead::of` reads a PDF's text layer first and withholds any file whose text names one of those numbers, answering with the redacted text instead; a scan's pixels cannot be redacted, and are handed over as they are.", rationale='Decided 2026-09-29 (the email-attachments-jakuay report). Restated 2026-11-20: the names moved with the crate split of 2026-11-18.', supersedes=()))